	"Main_Banner" => "الشعار الرئيسي",
	"this_banner_appears_at_the_top_of_your_website_or_app_to_grab_attention_instantly_and_showcase_offers_or_promotions._you_can_add_as_many_banners_as_you_like._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_3:2." => "يظهر هذا الشعار في الجزء العلوي من موقع الويب الخاص بك أو تطبيقك لجذب الانتباه على الفور وعرض العروض أو العروض الترويجية. يمكنك إضافة أي عدد تريده من اللافتات. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن نسبة الصورة 3:2.",
	"Popup_banner" => "لافتة منبثقة",
	"popup_banner_appears_when_user_visit_website._it’s_a_specific_single_type_banner._you_can_active_only_one_banner_at_a_time._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_1:1." => "يظهر الشعار المنبثق عندما يزور المستخدم موقع الويب. إنها لافتة من نوع واحد محدد. يمكنك تفعيل لافتة واحدة فقط في كل مرة. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجا بايت وأن نسبة الصورة 1:1.",
	"Footer_banner" => "شعار التذييل",
	"this_banner_appears_at_the_bottom_of_the_home_page_before_the_footer_section_to_grab_attention_when_any_on_browse_to_footer_section_and_showcase_offers_or_promotions._you_can_add_only_one_banner._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_4:1." => "يظهر هذا الشعار في أسفل الصفحة الرئيسية قبل قسم التذييل لجذب الانتباه عند التصفح إلى قسم التذييل وعرض العروض أو العروض الترويجية. يمكنك إضافة شعار واحد فقط. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن نسبة الصورة 4:1.",
	"Main_section_banner" => "راية القسم الرئيسي",
	"main_section_banner_appears_below_at_the_main_banner_of_your_website_grab_attention_instantly_and_showcase_offers_or_promotions._you_can_add_maximum_2_banners_at_a_time._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_2:1." => "يظهر شعار القسم الرئيسي أدناه على الشعار الرئيسي لموقع الويب الخاص بك لجذب الانتباه على الفور وعرض العروض أو العروض الترويجية. يمكنك إضافة شعارين بحد أقصى في المرة الواحدة. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن نسبة الصورة 2:1.",
	"this_banner_appears_at_the_header_nav_bar_section_to_showcase_short_&_effective_offers._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_4:1." => "يظهر هذا الشعار في قسم شريط التنقل في الرأس لعرض العروض القصيرة والفعالة. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن نسبة الصورة 4:1.",
	"this_banner_appears_at_the_right_side_of_the_intro_section_in_the_website._you_can_add_as_many_banners_as_you_like_but_only_show_one_banner_at_a_time_in_the_website._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_1:2." => "يظهر هذا الشعار على الجانب الأيمن من قسم المقدمة في الموقع. يمكنك إضافة أي عدد تريده من اللافتات ولكن يمكنك إظهار شعار واحد فقط في كل مرة على موقع الويب. عند التحميل، تأكد من أن حجم الملف أقل من 2 ميجا بايت وأن نسبة الصورة 1:2.",
	"Top_Sidebar_Banner" => "شعار الشريط الجانبي العلوي",
	"here_you_can_setup_vat_for_additional_charges." => "هنا يمكنك إعداد ضريبة القيمة المضافة مقابل رسوم إضافية.",
