	"You_can_apply_VAT/Taxes_order-wise,_product-wise,_category-wise,_ensuring_accurate_and_compliant_billing_across_all_operations." => "يمكنك تطبيق ضريبة القيمة المضافة/الضرائب حسب الطلب، حسب المنتج، حسب الفئة، مما يضمن إعداد فواتير دقيقة ومتوافقة عبر جميع العمليات.",
	"VAT_Calculation_Method" => "طريقة حساب ضريبة القيمة المضافة",
	"Include_in_Product_Price_When_you_select_Calculate_VAT/Tax_Included_in_Product_Price:" => "تضمين في سعر المنتج عند تحديد حساب ضريبة القيمة المضافة/الضريبة المضمنة في سعر المنتج:",
	"The_vat/tax_is_already_built_into_the_product_price." => "ضريبة القيمة المضافة/الضريبة مضمنة بالفعل في سعر المنتج.",
	"No_separate_vat/tax_line_will_be_shown_on_invoices_or_reports." => "لن يتم عرض أي سطر منفصل لضريبة القيمة المضافة/الضريبة في الفواتير أو التقارير.",
	"VAT/TAX_reports_will_not_be_generated_from_these_totals." => "لن يتم إنشاء تقارير ضريبة القيمة المضافة/الضريبة من هذه الإجماليات.",
	"Orders_will_show_a_label_like:_VAT/Tax_Included." => "ستظهر الطلبات تسمية مثل: ضريبة القيمة المضافة/الضريبة متضمنة.",
	"Exclude_from_Product_Price:" => "استبعاد من سعر المنتج:",
	"VAT/Tax_is_calculated_on_top_of_the_product_price_and_added_as_a_separate_amount." => "يتم احتساب ضريبة القيمة المضافة/الضريبة أعلى سعر المنتج ويتم إضافتها كمبلغ منفصل.",
	"The_VAT/TAX_appears_as_a_distinct_line_item_on_bills,_invoices,_and_order_summaries." => "تظهر ضريبة القيمة المضافة/الضريبة كبند مميز في الفواتير والفواتير وملخصات الطلبات.",
	"VAT/Tax_Effect_on_Order" => "تأثير ضريبة القيمة المضافة/الضريبة على الطلب",
