	"Orders_placed_before_the_VAT/Tax_status_is_turned_ON_will_be_calculated_without_VAT/Tax." => "سيتم حساب الطلبات المقدمة قبل تشغيل حالة ضريبة القيمة المضافة/الضريبة بدون ضريبة القيمة المضافة/الضريبة.",
	"The_system_will_not_apply_any_VAT/Tax_to_these_orders." => "لن يقوم النظام بتطبيق أي ضريبة القيمة المضافة/الضريبة على هذه الطلبات.",
	"After_Activating_VAT/TAX_Status" => "بعد تفعيل حالة ضريبة القيمة المضافة/الضريبة",
	"Once_the_VAT/Tax_status_is_activated_new_orders_placed_will_have_taxes_applied_based_on_your_VAT/Tax_setup." => "بمجرد تنشيط حالة ضريبة القيمة المضافة/الضريبة، سيتم تطبيق الضرائب على الطلبات الجديدة المقدمة بناءً على إعداد ضريبة القيمة المضافة/الضريبة.",
	"The_system_will_calculate_and_apply_the_correct_VAT/Tax_to_these_new_orders." => "سيقوم النظام بحساب وتطبيق ضريبة القيمة المضافة/الضريبة الصحيحة على هذه الطلبات الجديدة.",
	"If_Deactivating_VAT/Tax_Status:" => "في حالة إلغاء تنشيط ضريبة القيمة المضافة/الحالة الضريبية:",
	"If_the_VAT/Tax_status_is_deactivated_again_any_new_orders_placed_will_be_calculated_without_VAT/Tax." => "إذا تم إلغاء تنشيط حالة ضريبة القيمة المضافة/الضريبة مرة أخرى، فسيتم حساب أي طلبات جديدة مقدمة بدون ضريبة القيمة المضافة/الضريبة.",
	"VAT/Taxes_will_not_be_applied_to_the_new_orders_until_the_VAT/Tax_status_is_reactivated." => "لن يتم تطبيق ضريبة القيمة المضافة/الضرائب على الطلبات الجديدة حتى تتم إعادة تنشيط حالة ضريبة القيمة المضافة/الضريبة.",
	"Flexible_VAT/Tax_Application_Options" => "خيارات مرنة لتطبيق ضريبة القيمة المضافة/الضريبة",
	"VAT/Tax_can_be_applied_with_flexibility_depending_on_business_needs." => "يمكن تطبيق ضريبة القيمة المضافة/الضريبة بمرونة حسب احتياجات العمل.",
	"The_VAT/Tax_is_already_built_into_the_product_price." => "ضريبة القيمة المضافة/الضريبة مضمنة بالفعل في سعر المنتج.",
	"Order_Wise_VAT/Tax:_One_VAT/TAX_rate_applied_to_the_entire_order_total." => "طلب ضريبة القيمة المضافة/الضريبة: يتم تطبيق معدل ضريبة القيمة المضافة/الضريبة على إجمالي الطلب بالكامل.",
	"Product_Wise_VAT/Tax:_Different_VAT/TAX_rates_applied_individually_per_product." => "ضريبة القيمة المضافة/الضريبة على المنتج: يتم تطبيق معدلات ضريبة القيمة المضافة/الضريبة المختلفة بشكل فردي لكل منتج.",
	"Category_Wise_VAT/Tax:_Different_VAT/Tax_rates_apply_by_product_category." => "فئة ضريبة القيمة المضافة/الضريبة: تنطبق معدلات ضريبة القيمة المضافة/الضريبة المختلفة حسب فئة المنتج.",
	"Basic_Setup:" => "الإعداد الأساسي:",
	"In_the_basic_setup_you_can_select_VAT_type_(Order/Product/Category)" => "في الإعداد الأساسي، يمكنك تحديد نوع ضريبة القيمة المضافة (الطلب/المنتج/الفئة)",
	"You_can_also_select_one_or_multiple_VAT_rates_that_you_have_previously_created._The_selected_VAT/Tax_rates_will_be_automatically_applied_to_the_corresponding_order_product_or_category_during_calculation." => "يمكنك أيضًا تحديد معدل واحد أو عدة معدلات لضريبة القيمة المضافة التي قمت بإنشائها مسبقًا. سيتم تطبيق معدلات ضريبة القيمة المضافة/الضريبة المحددة تلقائيًا على منتج أو فئة الطلب المقابلة أثناء الحساب.",
	"The_Additional_Setup_section_allows_you_to_manage_how_taxes_are_applied_to_extra_charges." => "يسمح لك قسم الإعداد الإضافي بإدارة كيفية تطبيق الضرائب على الرسوم الإضافية.",
	"You_can_choose_whether_VAT/Tax_should_be_added_to_additional_fees_such_as_delivery_or_packaging_charges_associated_with_an_order." => "يمكنك اختيار ما إذا كان يجب إضافة ضريبة القيمة المضافة/الضريبة إلى الرسوم الإضافية مثل رسوم التوصيل أو التغليف المرتبطة بالطلب.",
	"Auction_Products" => "منتجات المزاد",
	"Explore_Auction" => "اكتشف المزاد",
	"Auction_Ending_Time" => "وقت انتهاء المزاد",
